<?php
/** TEMP PS S1631 run d — D: MIGRACIJOS LIKUČIŲ DRY-RUN (nieko nerašo). Products→paprastos publish prekės (trim, PET taisyklė; variantinių tėvai praleidžiami); Options→variacijos (kodas→atributas). Ataskaita: rašytina, praleista, savikainų padengimas partijoms. */
add_action('init', function(){
  if (!isset($_GET['ps_s1631d'])) return;
  $o=array('v'=>'S1631 d'); global $wpdb; $p=$wpdb->prefix;
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id, po.post_type, po.post_status FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r){ $map[trim((string)$r->sku)]=array((int)$r->post_id,$r->post_type,$r->post_status); }
  $gid=$wpdb->get_results("SELECT pm.meta_value g, pm.post_id, po.post_type, po.post_status FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type='product' WHERE pm.meta_key='_global_unique_id' AND pm.meta_value<>''");
  $gmap=array(); foreach($gid as $r){ $gmap[trim((string)$r->g)]=array((int)$r->post_id,$r->post_type,$r->post_status); }
  $norm=function($s){ $s=mb_strtolower(trim($s)); return str_replace(array('ė','ž','š','ų','ū','į','ą','č',' '),array('e','z','s','u','u','i','a','c',''),$s); };
  // savikainos is eksporto (Products faile jos nera CSV — imame is WP korteles; eksporto savikainas pridesim apply faze is pilnesnio CSV)
  $plan=array(); $pr_st=array('rasoma'=>0,'variantine_tevas'=>0,'draft_ar_kita'=>0,'nerasta'=>0,'kuponai'=>0); $q_ras=0;
  $nerasta=array(); $be_sav=0; $su_sav=0;
  foreach(array_filter(explode("\n",gzdecode(base64_decode('')))) as $l){ $c=explode(';',$l); $s=trim($c[0]); $e=trim($c[1]??''); $q=(int)($c[2]??0);
    if(strpos($s,'gift-coupon')===0){ $pr_st['kuponai']++; continue; }
    $hit=$map[$s] ?? $map['PET'===substr($s,0,3)?substr($s,3):$s] ?? ($e!==''?($gmap[$e]??null):null);
    if(!$hit && 'PET'===substr($s,0,3) && isset($map[substr($s,3)])) $hit=$map[substr($s,3)];
    if(!$hit){ $pr_st['nerasta']++; if(count($nerasta)<50)$nerasta[]=$s.' q'.$q; continue; }
    list($pid,$pt,$st)=$hit;
    if($st!=='publish'){ $pr_st['draft_ar_kita']++; continue; }
    $pr=wc_get_product($pid);
    if($pr && $pr->is_type('variable')){ $pr_st['variantine_tevas']++; continue; }
    $sav=(float)get_post_meta($pid,'_cost_price',true);
    if($sav>0)$su_sav++; else $be_sav++;
    $pr_st['rasoma']++; $q_ras+=$q;
    if(count($plan)<8)$plan[]=array('id'=>$pid,'sku'=>$s,'dabar'=>(int)get_post_meta($pid,'_stock',true),'bus'=>$q,'sav'=>$sav);
  }
  $o['paprastos']=$pr_st; $o['paprastu_q']=$q_ras; $o['savikaina']=array('kortele_yra'=>$su_sav,'nera'=>$be_sav);
  $o['nerasta_pvz']=$nerasta; $o['plan_pvz']=$plan;
  $v_st=array('kodu'=>0,'atributu'=>0,'ne_var'=>0,'nerasta'=>0); $vq=0; $v_pvz=array();
  foreach(array_filter(explode("\n",gzdecode(base64_decode('')))) as $l){ $c=explode(';',$l); list($bs,$at,$re,$vk,$q)=array(trim($c[0]),$c[1],trim($c[2]),trim($c[3]),(int)$c[4]);
    if(strpos($bs,'gift')===0) continue; $vid=0;
    if($vk!=='' && isset($map[$vk]) && $map[$vk][1]==='product_variation'){ $vid=$map[$vk][0]; $v_st['kodu']++; }
    elseif(isset($map[$bs])){ $pr=wc_get_product($map[$bs][0]);
      if($pr && $pr->is_type('variable')){ foreach($pr->get_children() as $cid){ $v=wc_get_product($cid); if(!$v)continue;
        foreach($v->get_attributes() as $tax=>$slug){ $t=get_term_by('slug',$slug,$tax); if($norm($t?$t->name:$slug)===$norm($re)){ $vid=$cid; break 2; } } }
        if($vid)$v_st['atributu']++; else $v_st['nerasta']++; }
      else $v_st['ne_var']++; }
    else $v_st['nerasta']++;
    if($vid){ $vq+=$q; if(count($v_pvz)<6)$v_pvz[]=array('vid'=>$vid,'sku'=>$bs,'re'=>$re,'dabar'=>(int)get_post_meta($vid,'_stock',true),'bus'=>$q); }
  }
  $o['variacijos']=$v_st; $o['variaciju_q']=$vq; $o['var_pvz']=$v_pvz;
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
